<?php
declare(strict_types=1);
namespace App\Domain\Review\Service;
use App\Domain\Review\Enum\ReviewRating;use App\Domain\Review\ValueObject\FlashcardProgressState;use App\Domain\Review\ValueObject\ReviewAlgorithmConfiguration;
final readonly class InitialSpacedRepetitionStrategy implements SpacedRepetitionStrategyInterface { public function __construct(private ReviewAlgorithmConfiguration $config){} public function next(FlashcardProgressState $s,ReviewRating $r,\DateTimeImmutable $now):FlashcardProgressState { if($r===ReviewRating::AGAIN)return new FlashcardProgressState($now->modify('+'.$this->config->againMinutes.' minutes'),0,max(1.3,$s->easeFactor-.2),0,$s->lapses+1);$base=match($r){ReviewRating::HARD=>$this->config->hardDays,ReviewRating::GOOD=>$this->config->goodDays,ReviewRating::EASY=>$this->config->easyDays,default=>1};$factor=match($r){ReviewRating::HARD=>.85,ReviewRating::GOOD=>1.0,ReviewRating::EASY=>1.3,default=>1.0};$days=max($base,(int)round(max(1,$s->intervalDays)*$s->easeFactor*$factor));$ease=max(1.3,$s->easeFactor+match($r){ReviewRating::HARD=>-.15,ReviewRating::GOOD=>0.0,ReviewRating::EASY=>.15,default=>0.0});return new FlashcardProgressState($now->modify('+'.$days.' days'),$days,$ease,$s->repetitions+1,$s->lapses); } }
